function PropertyPanel({
  unit = allUnits[2],
  onExplore,
  isVerified = false
}: {
  unit?: typeof allUnits[number]
  onExplore?: () => void
  isVerified?: boolean
}) {
  const [copied, setCopied] = useState(false)
  const fullId = identity(unit)

  const copyId = () => {
    navigator.clipboard?.writeText(fullId)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <section className="property-panel">
      <div className="panel-kicker">
        <div className="kicker-badge">
          <span className={`status-dot ${isVerified ? 'green' : 'amber'}`} />
          <span className="kicker-title">SELECTED PROPERTY</span>
        </div>
        <span className="panel-action" onClick={onExplore}>
          INSPECT <ArrowUpRight size={13} />
        </span>
      </div>

      <div className="property-header">
        <h2 className="property-id">{unit.ulpin}</h2>
        <div className="property-location">WARD 09 · CHENNAI URBAN</div>
      </div>

      <div className="identity-grid">
        <div className="identity-cell">
          <span className="cell-label">VERTICAL TAG</span>
          <span className="cell-value">{unit.verticalTag}</span>
        </div>
        <div className="identity-cell">
          <span className="cell-label">FLOOR</span>
          <span className="cell-value">{String(unit.floor).padStart(2, '0')} / ABOVE GROUND</span>
        </div>
        <div className="identity-cell">
          <span className="cell-label">VOLUMETRIC HASH</span>
          <span className="cell-value mono">{unit.volumetricHash}</span>
        </div>
        <div className="identity-cell">
          <span className="cell-label">CONFIDENCE</span>
          <span className="cell-value">{unit.confidence.toFixed(1)}%</span>
        </div>
      </div>

      <div className="proposed">
        <div className="proposed-meta">
          <span className="proposed-label">PROPOSED 3D ULPIN</span>
          <div style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
            <span className="proto-tag">PROTOTYPE ID</span>
            <button
              onClick={copyId}
              style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: '#0f766e', display: 'flex', alignItems: 'center' }}
              title="Copy ID"
            >
              {copied ? <Check size={12} /> : <Copy size={12} />}
            </button>
          </div>
        </div>
        <div className="proposed-value mono">{fullId}</div>
      </div>

      <div className="panel-status">
        <div className="status-main">
          <span className={`status-dot ${isVerified ? 'green' : 'amber'}`} />
          <span className="status-title">{isVerified ? 'VERIFIED RECORD' : 'PENDING VERIFICATION'}</span>
        </div>
        <span className="status-sub">
          {isVerified ? 'Authorized Officer Signed · Record Active' : 'Automated extraction complete'}
        </span>
      </div>

      {onExplore && (
        <Button onClick={onExplore} className="full">
          OPEN IN 3D EXPLORER <ArrowUpRight size={15} />
        </Button>
      )}
    </section>
  )
}

function Viewer({
  floor = 3,
  selectedUnit = allUnits[2],
  underground = false,
  fullScreen = false,
  onUnitSelect
}: {
  floor?: number
  selectedUnit?: typeof allUnits[number]
  underground?: boolean
  fullScreen?: boolean
  onUnitSelect?: (unit: typeof allUnits[number]) => void
}) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [layers, setLayers] = useState(layerNames().slice(0, 8))
  const [stack, setStack] = useState(false)
  const [under, setUnder] = useState(underground)
  const [panelOpen, setPanelOpen] = useState(false)
  const [activeUnit, setActiveUnit] = useState(selectedUnit)

  useEffect(() => {
    if (selectedUnit) {
      setActiveUnit(selectedUnit)
    }
  }, [selectedUnit])

  const handleSelectUnit = (unit: typeof allUnits[number]) => {
    setActiveUnit(unit)
    onUnitSelect?.(unit)
  }

  const toggleFullscreen = () => {
    if (containerRef.current) {
      if (document.fullscreenElement) {
        document.exitFullscreen?.()
      } else {
        containerRef.current.requestFullscreen?.()
      }
    }
  }

  const currentUnit = activeUnit || selectedUnit || allUnits[2]
  const currentFloor = currentUnit.floor || floor
  const currentTag = currentUnit.verticalTag || 'A03'

  return (
    <div ref={containerRef} className={`viewer ${!panelOpen ? 'viewer-expanded' : ''}`}>
      <SpatialScene
        floor={currentFloor}
        selectedUnitTag={currentTag}
        underground={under}
        verticalStack={stack}
        onSelectUnit={handleSelectUnit}
      />
      <div className="viewer-top-bar">
        <div className="viewer-title">
          <span className="eyebrow">{under ? 'UNDERGROUND SPATIAL VIEW' : 'URBAN DIGITAL TWIN'}</span>
          <b>{under ? 'Basements · utilities · property volumes' : 'Synthetic survey dataset / Chennai Urban'}</b>
          <div className="scene-scale">N ↑ &nbsp; 1 : 2,500 &nbsp; METRIC</div>
        </div>
        <div className="breadcrumb">
          <span>CITY</span> <ChevronRight size={12} />
          <span>PARCEL</span> <ChevronRight size={12} />
          <span>BUILDING</span> <ChevronRight size={12} />
          <span>FLOOR {String(currentFloor).padStart(2, '0')}</span> <ChevronRight size={12} />
          <b>UNIT {currentTag}</b>
        </div>
      </div>
      {panelOpen && (
        <div className="layer-control">
          <div className="panel-kicker">
            <span className="kicker-title">MAP LAYERS</span>
            <button className="layer-close-btn" onClick={() => setPanelOpen(false)} aria-label="Close layers panel">
              <X size={13} />
            </button>
          </div>
          <div className="layer-list">
            {layerNames().map(name => (
              <label key={name} className="layer-checkbox">
                <input
                  type="checkbox"
                  checked={layers.includes(name)}
                  onChange={() => setLayers(layers.includes(name) ? layers.filter(x => x !== name) : [...layers, name])}
                />
                <span>{name}</span>
              </label>
            ))}
          </div>
        </div>
      )}
      <div className="viewer-bottom-bar">
        <div className="scene-legend">
          <span><i className="legend-building" /> BUILDING</span>
          <span><i className="legend-unit" /> PROPERTY UNIT</span>
          <span><i className="legend-utility" /> UTILITY ROUTE</span>
          <span><i className="legend-survey" /> SURVEY POINT</span>
        </div>
        <div className="viewer-tools">
          <Button variant="outline" onClick={() => setStack(!stack)}>
            <Layers3 size={14} /> {stack ? 'COLLAPSE STACK' : 'VERTICAL STACK'}
          </Button>
          <Button variant={under ? 'primary' : 'outline'} onClick={() => setUnder(!under)}>
            <Waypoints size={14} /> {under ? 'ABOVE GROUND' : 'REVEAL UNDERGROUND'}
          </Button>
          <Button
            variant="quiet"
            onClick={() => {
              setStack(false)
              setUnder(false)
            }}
          >
            RESET CAMERA
          </Button>
          <Button variant="quiet" onClick={toggleFullscreen}>
            <Maximize2 size={14} /> FULL SCREEN
          </Button>
          <Button variant={panelOpen ? 'primary' : 'quiet'} onClick={() => setPanelOpen(!panelOpen)}>
            <PanelRightClose size={14} /> {panelOpen ? 'HIDE LAYERS' : 'MAP LAYERS'}
          </Button>
        </div>
      </div>
    </div>
  )
}

