function Explorer({
  selectedUnit,
  onSelectUnit
}: {
  selectedUnit: typeof allUnits[number]
  onSelectUnit: (unit: typeof allUnits[number]) => void
}) {
  const [query, setQuery] = useState('TN09-10821')

  const handleSearch = (val: string) => {
    setQuery(val)
    const upper = val.toUpperCase().trim()
    const match = allUnits.find(
      u => u.verticalTag.toUpperCase() === upper || u.unitNumber.toUpperCase() === upper || u.id.toUpperCase() === upper
    )
    if (match) {
      onSelectUnit(match)
    }
  }

  return (
    <div className="explorer-page">
      <div className="page-head compact">
        <div className="page-title-block">
          <span className="eyebrow">FLAGSHIP VIEW</span>
          <h1>3D Explorer</h1>
          <p>City / parcel / building / floor / unit hierarchy</p>
        </div>
        <div className="search">
          <Search size={16} className="search-icon" />
          <input
            placeholder="Search unit (e.g. A101, A203, A301)..."
            value={query}
            onChange={e => handleSearch(e.target.value)}
          />
          <kbd className="search-kbd">⌘ K</kbd>
        </div>
      </div>
      <div className="explorer-grid">
        <Viewer selectedUnit={selectedUnit} onUnitSelect={onSelectUnit} />
        <PropertyPanel unit={selectedUnit} />
      </div>
    </div>
  )
}

