export default function OperationsShell({ view = 'overview' }: { view?: string }) {
  const router = useRouter()
  const pathname = usePathname()

  // Initialize view from pathname or prop
  const getViewFromPath = (path: string) => {
    const clean = path.replace(/^\//, '').split('/')[0]
    if (!clean) return 'overview'
    if (clean === 'property-detail') return 'property'
    return clean
  }

  const [currentView, setCurrentView] = useState<string>(() => {
    if (typeof window !== 'undefined' && window.location.pathname) {
      return getViewFromPath(window.location.pathname)
    }
    return view
  })

  const [selectedUnit, setSelectedUnit] = useState<typeof allUnits[number]>(allUnits[2])

  useEffect(() => {
    if (pathname) {
      const detected = getViewFromPath(pathname)
      setCurrentView(detected)
    }
  }, [pathname])

  const handleNavigate = (targetView: string) => {
    setCurrentView(targetView)
    const newPath = targetView === 'overview' ? '/' : `/${targetView}`
    try {
      window.history.pushState(null, '', newPath)
      router.push(newPath)
    } catch {
      // fallback
    }
  }

  const isExplorer = currentView === 'explorer'

  let content: React.ReactNode = (
    <Overview onNavigate={handleNavigate} onSelectUnit={setSelectedUnit} selectedUnit={selectedUnit} />
  )
  if (currentView === 'explorer') {
    content = <Explorer selectedUnit={selectedUnit} onSelectUnit={setSelectedUnit} />
  }
  if (currentView === 'generate') {
    content = <Generate onNavigate={handleNavigate} />
  }
  if (currentView === 'validation') {
    content = <Validation onNavigate={handleNavigate} onSelectUnit={setSelectedUnit} />
  }
  if (currentView === 'conflicts') {
    content = <Conflicts />
  }
  if (currentView === 'property-detail' || currentView === 'property') {
    content = <Dossier selectedUnit={selectedUnit} onSelectUnit={setSelectedUnit} onNavigate={handleNavigate} />
  }

  return (
    <div className={`app-shell ${isExplorer ? 'explorer-shell' : ''}`}>
      <Topbar onNavigate={handleNavigate} />
      <Sidebar active={currentView} onNavigate={handleNavigate} />
      <main className={`content ${isExplorer ? 'content-explorer' : ''}`}>
        {content}
        {!isExplorer && (
          <footer>
            <span>SIH26011 · SMART AUTOMATION</span>
            <span>LOCAL DEMONSTRATION MAP · MOCK SERVICES ENABLED</span>
            <span>31 AUG 2026</span>
          </footer>
        )}
      </main>
    </div>
  )
}
